          'فيديو قصير يشرح كيفية العثور على القطعة المناسبة في غضون دقائق قليلة والحصول على تعليقات من البائعين.',
      'az':
          'Bir neçə dəqiqə ərzində düzgün hissəni necə tapmaq və satıcılardan rəy almaq barədə qısa bir video.',
      'be':
          'Кароткае відэа аб тым, як знайсці патрэбную запчастку за пару хвілін і атрымаць водгукі ад прадаўцоў.',
      'bg':
          'Кратко видео за това как да намерите правилната част за няколко минути и да получите обратна връзка от продавачите.',
      'cs':
          'Krátké video o tom, jak najít ten správný díl během pár minut a získat zpětnou vazbu od prodejců.',
      'de':
          'Ein kurzes Video darüber, wie man in wenigen Minuten das richtige Ersatzteil findet und Feedback von Verkäufern erhält.',
      'en':
          'A short video about how to find the right part in a couple of minutes and get feedback from sellers.',
      'es':
          'Un breve vídeo sobre cómo encontrar la pieza adecuada en un par de minutos y obtener opiniones de los vendedores.',
      'et':
          'Lühike video sellest, kuidas leida õige osa paari minutiga ja saada müüjatelt tagasisidet.',
      'fr':
          'Une courte vidéo expliquant comment trouver la pièce qu\'il vous faut en quelques minutes et obtenir des avis de vendeurs.',
      'hi':
          'कुछ ही मिनटों में सही पार्ट ढूंढने और विक्रेताओं से फीडबैक प्राप्त करने के तरीके के बारे में एक छोटा वीडियो।',
      'hy':
          'Կարճ տեսանյութ այն մասին, թե ինչպես մի քանի րոպեում գտնել ճիշտ մասը և ստանալ վաճառողներից արձագանքներ։',
      'ja': '数分で適切な部品を見つけ、販売者からフィードバックを得る方法についての短いビデオです。',
      'ka':
          'მოკლე ვიდეო იმის შესახებ, თუ როგორ იპოვოთ სწორი ნაწილი რამდენიმე წუთში და მიიღოთ გამოხმაურება გამყიდველებისგან.',
      'kk':
          'Бірнеше минут ішінде дұрыс бөлшекті қалай табуға және сатушылардан кері байланыс алуға болатыны туралы қысқаша бейне.',
      'ko': '몇 분 안에 적합한 부품을 찾고 판매자로부터 피드백을 받는 방법에 대한 짧은 동영상입니다.',
      'ky':
          'Бир нече мүнөттүн ичинде туура тетикти кантип табуу жана сатуучулардан пикир алуу жөнүндө кыска видео.',
      'lv':
          'Īss video par to, kā pāris minūtēs atrast pareizo detaļu un saņemt atsauksmes no pārdevējiem.',
      'pl':
          'Krótki film pokazujący, jak znaleźć odpowiednią część w ciągu kilku minut i uzyskać opinie od sprzedawców.',
      'ro':
          'Un scurt videoclip despre cum să găsești piesa potrivită în câteva minute și să primești feedback de la vânzători.',
      'sk':
          'Krátke video o tom, ako nájsť správny diel za pár minút a získať spätnú väzbu od predajcov.',
      'th':
          'วิดีโอสั้นๆ เกี่ยวกับวิธีการค้นหาชิ้นส่วนที่ถูกต้องภายในเวลาไม่กี่นาที และรับข้อเสนอแนะจากผู้ขาย',
      'tr':
          'Birkaç dakika içinde doğru parçayı nasıl bulacağınızı ve satıcılardan nasıl geri bildirim alacağınızı anlatan kısa bir video.',
      'uk':
          'Коротке відео про те, як знайти потрібну запчастину за пару хвилин та отримати відгуки від продавців.',
      'uz':
          'Bir necha daqiqada to\'g\'ri qismni qanday topish va sotuvchilardan fikr-mulohazalarni olish haqida qisqa video.',
      'zh_Hant': '一段簡短的視頻，教你如何在幾分鐘內找到合適的零件並獲得賣家的反饋。',
