      'ja': 'この動画では、販売フィルターの追加方法、販売者プロフィールの設定方法、そして適切な問い合わせにいち早く対応する方法を解説します。',
      'ka':
          'ეს ვიდეო განმარტავს, თუ როგორ დაამატოთ გაყიდვების ფილტრი, შექმნათ გამყიდველის პროფილი და იყოთ პირველი, ვინც უპასუხებს შესაბამის შეკითხვებს.',
      'kk':
          'Бұл бейнеде сату сүзгісін қалай қосу, сатушы профилін қалай орнату және тиісті сұрауларға бірінші болып жауап беру жолдары түсіндіріледі.',
      'ko':
