      'pl':
          'W tym filmie dowiesz się, jak dodać filtr sprzedaży, skonfigurować profil sprzedawcy i jak jako pierwszy odpowiadać na odpowiednie zapytania.',
      'ro':
          'Acest videoclip explică cum să adaugi un filtru de vânzări, să configurezi un profil de vânzător și să fii primul care răspunde la solicitări adecvate.',
      'sk':
          'Toto video vysvetľuje, ako pridať filter predaja, nastaviť profil predajcu a ako prvý odpovedať na vhodné otázky.',
